css:
@page {
    size: A4;
    margin: 0;
}

html, body {
    width: 210mm;
    height: 297mm;
    margin: 0;
    padding: 0;
}

body {
    font-family: "Times New Roman", serif;
    font-size: 14.5px;
    line-height: 1.6;
    color: #000;
    margin: 0;
    padding: 0;
}

.page {
    position: relative;
    width: 210mm;
    height: 297mm;
    margin: 0;
    overflow: hidden;
    background-image: url("/assets/sahayog/images/letter_head_and_footer_.png");
    background-size: cover;        /* Cover entire area, no white borders */
    background-position: center;   /* Centered image */
    background-repeat: no-repeat;
    box-sizing: border-box;
}

@media print {
    html, body {
        width: 210mm;
        height: 297mm;
        margin: 0;
        padding: 0;
    }
    .page {
        margin: 0;
        box-shadow: none;
    }
}

/* Content styling */
.page .content {
    position: absolute;
    top: 45%;
    left: 50%;
    transform: translate(-50%, -50%);
    width: 80%;
    z-index: 2;
    box-sizing: border-box;
}

.content h2 {
    text-align: center;
    margin-bottom: 20px;
    font-size: 22px;
    font-weight: bold;
}

.content p {
    margin: 0 0 12px 0;
    font-size: 15px;
    text-align: justify;
}

.signature {
    margin-top: 40px;
    font-size: 15px;
    font-weight: bold;
}
